import{_ as o,o as d,c,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Sets-of-Variables.md","filePath":"manual-zh/Sets-of-Variables.md","lastUpdated":1785684581000}'),t={name:"manual-zh/Sets-of-Variables.md"};function T(r,e,s,_,n,l){return d(),c("div",null,[...e[0]||(e[0]=[a('<h4 id="_6-7-3-变量名列表" tabindex="-1">6.7.3 变量名列表 <a class="header-anchor" href="#_6-7-3-变量名列表" aria-label="Permalink to &quot;6.7.3 变量名列表&quot;">​</a></h4><p>要引用一组变量，将它们名称依次列出即可。可选地，名称之间可以用逗号分隔。要将字典中某个范围的变量包含进列表，写出该范围中第一个和最后一个变量的名称，用 <code>TO</code> 分隔。例如，如果字典中按顺序包含六个名为 <code>ID</code>、<code>X1</code>、<code>X2</code>、<code>GOAL</code>、<code>MET</code> 和 <code>NEXTGOAL</code> 的变量，那么 <code>X2 TO MET</code> 将包含变量 <code>X2</code>、<code>GOAL</code> 和 <code>MET</code>。</p><p>定义变量的命令（如 <code>DATA LIST</code>）赋予 <code>TO</code> 另一种含义。在这些命令中，<code>TO</code> 定义名称以连续整数结尾的变量序列。语法为两个以相同词根开头、以数字结尾的标识符，用 <code>TO</code> 分隔。语法 <code>X1 TO X5</code> 定义了 5 个变量，名为 <code>X1</code>、<code>X2</code>、<code>X3</code>、<code>X4</code> 和 <code>X5</code>。语法 <code>ITEM0008 TO ITEM0013</code> 定义了 6 个变量，名为 <code>ITEM0008</code>、<code>ITEM0009</code>、<code>ITEM0010</code>、<code>ITEM0011</code>、<code>ITEM0012</code> 和 <code>ITEM00013</code>。语法 <code>QUES001 TO QUES9</code> 和 <code>QUES6 TO QUES3</code> 是无效的。</p><p>用 <code>DATA LIST</code> 或采用此方法的另一条命令定义一组变量之后，后续命令可以使用相同的语法引用同一组变量。</p>',4)])])}const E=o(t,[["render",T]]);export{p as __pageData,E as default};
